mapper.insert:
insert into asset_requirement (
    id, project_id, code, title, description, source, priority, status, tags, created_at, updated_at
) values (
    #{id}, #{projectId}, concat('REQ-', substr(replace(#{id}::text, '-', ''), 1, 12)),
    #{title}, #{description}, 'MANUAL', #{priority}, #{status}, #{tags}, #{createdAt}, #{updatedAt}
)

insert into asset_api (
    id, project_id, code, path, http_method, summary, description, source,
    request_schema, response_schema, status, created_at, updated_at
) values (
    #{id}, #{projectId}, concat('API-', substr(replace(#{id}::text, '-', ''), 1, 12)),
    #{path}, #{httpMethod}, #{summary}, #{description}, 'MANUAL',
    cast(coalesce(#{requestSchema}, '{}') as jsonb),
    cast(coalesce(#{responseSchema}, '{}') as jsonb),
    #{status}, #{createdAt}, #{updatedAt}
)

insert into asset_page (
    id, project_id, code, name, url_pattern, source, source_ref,
    component_tree, screenshot_url, status, created_at, updated_at
) values (
    #{id}, #{projectId}, concat('PAGE-', substr(replace(#{id}::text, '-', ''), 1, 12)),
    #{name}, #{urlPattern}, #{source}, #{sourceRef},
    cast(coalesce(#{componentTree}, '{}') as jsonb),
    #{screenshotUrl}, #{status}, #{createdAt}, #{updatedAt}
)

insert into asset_business_flow (
    id, project_id, code, name, description, flow_json, priority, status, created_at, updated_at
) values (
    #{id}, #{projectId}, concat('FLOW-', substr(replace(#{id}::text, '-', ''), 1, 12)),
    #{name}, #{description}, cast(coalesce(#{flowJson}, '{}') as jsonb),
    #{priority}, #{status}, #{createdAt}, #{updatedAt}
)

insert into asset_test_case (
    id, project_id, code, title, description, priority, status, tags, created_at, updated_at
) values (
    #{id}, #{projectId}, concat('TC-', substr(replace(#{id}::text, '-', ''), 1, 12)),
    #{title}, #{description}, #{priority}, #{status}, #{tags}, #{createdAt}, #{updatedAt}
)

insert into asset_test_step (
    id, case_id, step_order, action, expected_result
) values (
    #{id}, #{caseId}, #{stepOrder}, #{action}, #{expectedResult}
)

insert into asset_link (
    id, source_type, source_id, target_type, target_id, link_type, created_at
)
select #{id}, 'REQUIREMENT', #{requirementId}, 'CASE', #{caseId}, 'VERIFIES', #{createdAt}
where #{caseId} is not null
union all
select gen_random_uuid(), 'REQUIREMENT', #{requirementId}, 'API', #{apiId}, 'COVERS', #{createdAt}
where #{apiId} is not null
on conflict do nothing
